private val Bg=Color(0xFF0D1117);private val Header=Color(0xFF131722);private val Card=Color(0xFF1E222D)
private val Green=Color(0xFF26A69A);private val Muted=Color(0xFF787B86);private val Red=Color(0xFFEF5350)
const val APP_VERSION="1.0.2"
const val UPDATE_MANIFEST="https://raw.githubusercontent.com/akramwasimjmi1994-wq/NSE-Bullish-Scanner/main/update.json"
data class StockRow(val symbol:String,val price:Double,val score:Int,val rsi:Double,val adx:Double,val relVol:Double,val trend:String,val signal:String)
data class UiState(val running:Boolean=false,val done:Int=0,val total:Int=0,val rows:List<StockRow> = emptyList(),val error:String?=null)
data class CheckState(val running:Boolean=false,val message:String="",val url:String?=null)
data class PaperPosition(val symbol:String,val qty:Int,val avgPrice:Double,var ltp:Double)

class ScannerVm:ViewModel(){
 var state by mutableStateOf(UiState());private set
 var universe by mutableStateOf("Nifty 50");var timeframe by mutableStateOf("1 day");var minimum by mutableIntStateOf(70)
 var update by mutableStateOf(CheckState());private set
 var paperCash by mutableDoubleStateOf(100000.0);var paperRealized by mutableDoubleStateOf(0.0)
 var paperPositions by mutableStateOf(listOf<PaperPosition>());var paperMessage by mutableStateOf("")
 private val client=YahooClient()
 fun scan(){if(state.running)return;val syms=Universe.symbols(universe);state=UiState(true,0,syms.size);viewModelScope.launch{val out=mutableListOf<StockRow>();for(batch in syms.chunked(8)){val rs=batch.map{s->async(Dispatchers.IO){client.scan(s,timeframe)}}.awaitAll();rs.filterNotNull().forEach{row->if(row.score>=minimum)out.add(row)};state=state.copy(done=minOf(state.done+batch.size,syms.size),rows=out.sortedByDescending{it.score})};state=state.copy(running=false)}}
 suspend fun checkOne(symbol:String,tf:String)=client.scan(symbol,tf)
 fun checkUpdate(){if(update.running)return;update=CheckState(true,"Checking for updates…");viewModelScope.launch(Dispatchers.IO){val r=runCatching{client.checkAndroidUpdate(UPDATE_MANIFEST,APP_VERSION)}.getOrElse{e->CheckResult(false,"Update check failed: "+e.message,null)};update=CheckState(false,r.message,r.url)}}
 fun buy(symbol:String,qty:Int,price:Double){if(qty<=0||price<=0)return;val cost=qty*price;if(cost>paperCash){paperMessage="Insufficient virtual cash";return};val old=paperPositions.find{it.symbol==symbol};val pos=if(old==null)PaperPosition(symbol,qty,price,price)else PaperPosition(symbol,old.qty+qty,(old.avgPrice*old.qty+price*qty)/(old.qty+qty),price);paperCash-=cost;paperPositions=paperPositions.filterNot{it.symbol==symbol}+pos;paperMessage="PAPER BUY: $qty $symbol @ ₹"+fmt(price)}
 fun sell(symbol:String,qty:Int,price:Double){val old=paperPositions.find{it.symbol==symbol}?:run{paperMessage="No open position in $symbol";return};if(qty<=0||qty>old.qty){paperMessage="Sell quantity exceeds open position";return};val pnl=(price-old.avgPrice)*qty;paperCash+=qty*price;paperRealized+=pnl;paperPositions=if(qty==old.qty)paperPositions.filterNot{it.symbol==symbol}else paperPositions.map{if(it.symbol==symbol)it.copy(qty=old.qty-qty,ltp=price)else it};paperMessage="PAPER SELL: $qty $symbol @ ₹"+fmt(price)+" | P&L ₹"+fmt(pnl)}
 fun refreshPosition(symbol:String,price:Double){paperPositions=paperPositions.map{if(it.symbol==symbol)it.copy(ltp=price)else it}}
 fun resetPaper(){paperCash=100000.0;paperRealized=0.0;paperPositions=emptyList();paperMessage="Paper account reset to ₹1,00,000"}
 fun openPnl()=paperPositions.sumOf{(it.ltp-it.avgPrice)*it.qty}
 fun equity()=paperCash+paperPositions.sumOf{it.ltp*it.qty}
}
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{App()}}}
@Composable fun App(){
 val ctx=LocalContext.current;val vm=remember{ScannerVm()};val s=vm.state;val u=vm.update;var tab by remember{mutableIntStateOf(0)}
 MaterialTheme(colorScheme=darkColorScheme(primary=Green,background=Bg,surface=Card,onSurface=Color(0xFFD1D4DC))){Surface(Modifier.fillMaxSize(),color=Bg){Column{
  Row(Modifier.fillMaxWidth().background(Header).padding(12.dp),verticalAlignment=Alignment.CenterVertically){Text("NSE",color=Green,fontWeight=FontWeight.Bold);Spacer(Modifier.width(6.dp));Text("BULLISH TERMINAL",fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));TextButton(onClick={vm.checkUpdate()},enabled=!u.running){Text("UPDATE",color=Green,fontSize=11.sp)};Text("v"+APP_VERSION,color=Muted,fontSize=10.sp)}
  if(u.message.isNotBlank()){Row(Modifier.fillMaxWidth().background(Card).padding(6.dp),verticalAlignment=Alignment.CenterVertically){Text(u.message,color=if(u.url!=null)Green else Muted,fontSize=11.sp,modifier=Modifier.weight(1f));if(u.url!=null)TextButton(onClick={ctx.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(u.url)))}){Text("DOWNLOAD",color=Green,fontSize=10.sp)}}}
  TabRow(selectedTabIndex=tab,containerColor=Header){Tab(tab==0,{tab=0},text={Text("MARKET SCANNER")});Tab(tab==1,{tab=1},text={Text("STOCK CHECK")});Tab(tab==2,{tab=2},text={Text("PAPER TRADE")})}
  when(tab){0->ScannerScreen(vm,s);1->StockCheckScreen(vm);2->PaperTradeScreen(vm)}
 }}}
}
@Composable fun ScannerScreen(vm:ScannerVm,s:UiState){Column(Modifier.padding(12.dp)){Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.fillMaxWidth()){Choice(vm.universe,listOf("Nifty 50","Nifty 100","Nifty 200"),{vm.universe=it},Modifier.weight(1f));Choice(vm.timeframe,listOf("15 min","1 hour","1 day"),{vm.timeframe=it},Modifier.weight(1f))};Spacer(Modifier.height(8.dp));Row(verticalAlignment=Alignment.CenterVertically){Text("MIN SCORE",color=Muted,fontSize=11.sp);Slider(value=vm.minimum.toFloat(),onValueChange={vm.minimum=(it/5).toInt()*5},valueRange=50f..100f,steps=9,modifier=Modifier.weight(1f));Text(vm.minimum.toString()+"/100",fontWeight=FontWeight.Bold)};Button(onClick={vm.scan()},enabled=!s.running,modifier=Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Green),shape=RoundedCornerShape(8.dp)){Text(if(s.running)"SCANNING…" else "⚡ SCAN MARKET")};Spacer(Modifier.height(8.dp));Text(if(s.total>0)s.done.toString()+" / "+s.total+" stocks scanned" else "READY — press Scan Market",color=Muted);if(s.running)LinearProgressIndicator(progress={if(s.total==0)0f else s.done.toFloat()/s.total},modifier=Modifier.fillMaxWidth().padding(vertical=6.dp),color=Green);Row(horizontalArrangement=Arrangement.spacedBy(6.dp),modifier=Modifier.fillMaxWidth()){Kpi("SCANNED",s.done.toString(),Modifier.weight(1f));Kpi("BUY",s.rows.count{it.signal=="BUY"}.toString(),Modifier.weight(1f));Kpi("SHOWN",s.rows.size.toString(),Modifier.weight(1f))}};LazyColumn(Modifier.fillMaxSize().padding(horizontal=12.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){items(s.rows,key={it.symbol}){StockCard(it)}}}
@Composable fun StockCheckScreen(vm:ScannerVm){var symbol by remember{mutableStateOf("")};var tf by remember{mutableStateOf("1 day")};var loading by remember{mutableStateOf(false)};var result by remember{mutableStateOf<StockRow?>(null)};var error by remember{mutableStateOf("")};Column(Modifier.padding(12.dp)){Text("CHECK PARTICULAR STOCK",fontWeight=FontWeight.Bold);Text("Runs the bullish signal calculation used by the scanner.",color=Muted,fontSize=11.sp);Spacer(Modifier.height(8.dp));OutlinedTextField(value=symbol,onValueChange={symbol=it.uppercase(Locale.US).replace(".NS","")},singleLine=true,label={Text("NSE Symbol")},placeholder={Text("e.g. RELIANCE")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(8.dp));Choice(tf,listOf("15 min","1 hour","1 day"),{tf=it},Modifier.fillMaxWidth());Spacer(Modifier.height(8.dp));Button(enabled=!loading&&symbol.isNotBlank(),onClick={loading=true;result=null;error="";vm.viewModelScope.launch{val r=vm.checkOne(symbol.trim(),tf);loading=false;if(r==null)error="Unable to fetch market data." else result=r}},modifier=Modifier.fillMaxWidth(),colors=ButtonDefaults.buttonColors(containerColor=Green)){Text(if(loading)"CHECKING…" else "CHECK BUY SIGNAL")};if(error.isNotBlank())Text(error,color=Red,modifier=Modifier.padding(top=8.dp));result?.let{StockCheckResult(it)}}}
@Composable fun StockCheckResult(r:StockRow){Spacer(Modifier.height(12.dp));Card(colors=CardDefaults.cardColors(containerColor=Header),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(14.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text(r.symbol,fontWeight=FontWeight.Bold,fontSize=20.sp);Spacer(Modifier.weight(1f));Text(r.signal,color=if(r.signal=="BUY")Green else Red,fontWeight=FontWeight.Bold,fontSize=18.sp)};Text("Composite score: "+r.score+"/100",color=Muted);Spacer(Modifier.height(10.dp));Row(horizontalArrangement=Arrangement.spacedBy(14.dp)){Metric("Price","₹"+fmt(r.price));Metric("RSI",String.format(Locale.US,"%.1f",r.rsi));Metric("ADX",String.format(Locale.US,"%.1f",r.adx));Metric("RelVol",String.format(Locale.US,"%.2f",r.relVol))};Text("Trend: "+r.trend,color=if(r.trend=="BULLISH")Green else Red,fontSize=12.sp,modifier=Modifier.padding(top=8.dp))}}}
@Composable fun PaperTradeScreen(vm:ScannerVm){
 var symbol by remember{mutableStateOf("")};var qtyText by remember{mutableStateOf("1")};var price by remember{mutableStateOf<Double?>(null)};var loading by remember{mutableStateOf(false)};val clean=symbol.uppercase(Locale.US).replace(".NS","").trim();val qty=qtyText.toIntOrNull()?:0
 Column(Modifier.fillMaxSize().padding(12.dp)){Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("PAPER TRADING",fontWeight=FontWeight.Bold,fontSize=18.sp);Text("Virtual money only — no real orders are placed.",color=Muted,fontSize=11.sp)};TextButton(onClick={vm.resetPaper()}){Text("RESET",color=Red,fontSize=11.sp)}};Spacer(Modifier.height(8.dp));Row(horizontalArrangement=Arrangement.spacedBy(6.dp),modifier=Modifier.fillMaxWidth()){Kpi("CASH","₹"+fmt(vm.paperCash),Modifier.weight(1f));Kpi("EQUITY","₹"+fmt(vm.equity()),Modifier.weight(1f));Kpi("OPEN P&L","₹"+fmt(vm.openPnl()),Modifier.weight(1f))};Spacer(Modifier.height(10.dp));OutlinedTextField(value=symbol,onValueChange={symbol=it.uppercase(Locale.US).replace(".NS","")},singleLine=true,label={Text("NSE Symbol")},placeholder={Text("e.g. RELIANCE")},modifier=Modifier.fillMaxWidth());Spacer(Modifier.height(6.dp));Row(horizontalArrangement=Arrangement.spacedBy(6.dp),verticalAlignment=Alignment.CenterVertically){OutlinedTextField(value=qtyText,onValueChange={qtyText=it.filter{c->c.isDigit()}},singleLine=true,label={Text("Quantity")},modifier=Modifier.weight(1f));Button(enabled=!loading&&clean.isNotBlank(),onClick={loading=true;vm.viewModelScope.launch{val r=vm.checkOne(clean,"1 day");loading=false;price=r?.price;if(r==null)vm.paperMessage="Unable to fetch price"}},colors=ButtonDefaults.buttonColors(containerColor=Header)){Text(if(loading)"…" else "GET PRICE")}};if(price!=null)Text("Current price: ₹"+fmt(price!!),color=Green,fontSize=12.sp,modifier=Modifier.padding(top=6.dp));Spacer(Modifier.height(6.dp));Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.fillMaxWidth()){Button(enabled=price!=null&&qty>0,onClick={vm.buy(clean,qty,price?:0.0)},modifier=Modifier.weight(1f),colors=ButtonDefaults.buttonColors(containerColor=Green)){Text("PAPER BUY")};Button(enabled=price!=null&&qty>0,onClick={vm.sell(clean,qty,price?:0.0)},modifier=Modifier.weight(1f),colors=ButtonDefaults.buttonColors(containerColor=Red)){Text("PAPER SELL")}};if(vm.paperMessage.isNotBlank())Text(vm.paperMessage,color=Muted,fontSize=11.sp,modifier=Modifier.padding(vertical=6.dp));Text("OPEN POSITIONS",fontWeight=FontWeight.Bold);if(vm.paperPositions.isEmpty())Text("No open paper positions.",color=Muted,fontSize=12.sp,modifier=Modifier.padding(top=8.dp));LazyColumn(Modifier.fillMaxWidth().weight(1f),verticalArrangement=Arrangement.spacedBy(6.dp)){items(vm.paperPositions,key={it.symbol}){p->val pnl=(p.ltp-p.avgPrice)*p.qty;Card(colors=CardDefaults.cardColors(containerColor=Header),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(10.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text(p.symbol,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text("₹"+fmt(pnl),color=if(pnl>=0)Green else Red,fontWeight=FontWeight.Bold)};Row(horizontalArrangement=Arrangement.spacedBy(16.dp)){Metric("Qty",p.qty.toString());Metric("Avg","₹"+fmt(p.avgPrice));Metric("LTP","₹"+fmt(p.ltp))};TextButton(onClick={vm.viewModelScope.launch{val r=vm.checkOne(p.symbol,"1 day");if(r!=null)vm.refreshPosition(p.symbol,r.price)}}){Text("REFRESH PRICE",color=Green,fontSize=10.sp)}}}}};Text("Realized P&L: ₹"+fmt(vm.paperRealized)+" | Starting capital: ₹1,00,000",color=Muted,fontSize=10.sp)}
}
fun fmt(v:Double)=String.format(Locale.US,"%,.2f",v)
@Composable fun Choice(value:String,items:List<String>,onPick:(String)->Unit,modifier:Modifier=Modifier){var open by remember{mutableStateOf(false)};Box(modifier){OutlinedButton(onClick={open=true},modifier=Modifier.fillMaxWidth()){Text(value,fontSize=12.sp)};DropdownMenu(expanded=open,onDismissRequest={open=false}){items.forEach{item->DropdownMenuItem(text={Text(item)},onClick={onPick(item);open=false})}}}}
@Composable fun Kpi(title:String,value:String,modifier:Modifier){Card(colors=CardDefaults.cardColors(containerColor=Card),modifier=modifier){Column(Modifier.padding(8.dp)){Text(title,color=Muted,fontSize=10.sp);Text(value,fontWeight=FontWeight.Bold,fontSize=12.sp)}}}
@Composable fun StockCard(r:StockRow){Card(colors=CardDefaults.cardColors(containerColor=Header),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text(r.symbol,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));Text(r.signal,color=if(r.signal=="BUY")Green else Muted,fontWeight=FontWeight.Bold);Text(" "+r.score+"/100")};Row(horizontalArrangement=Arrangement.spacedBy(12.dp)){Metric("Price","₹"+fmt(r.price));Metric("RSI",String.format(Locale.US,"%.1f",r.rsi));Metric("ADX",String.format(Locale.US,"%.1f",r.adx));Metric("RelVol",String.format(Locale.US,"%.2f",r.relVol))};Text(r.trend,color=if(r.trend=="BULLISH")Green else Red,fontSize=11.sp)}}}
@Composable fun Metric(a:String,b:String){Column{Text(a,color=Muted,fontSize=9.sp);Text(b,fontSize=12.sp,fontWeight=FontWeight.SemiBold)}}
